def ichol(A):
    M, N = A.shape
    if M != N or not np.allclose(A, A.T): raise ValueError("Matrix is not square or symmetric")
    L = np.zeros_like(A)
    for i in range(M):
        if A[i,i] == 0: raise ValueError("Matrix has zero diagonal entry")
        L[i,i] = np.sqrt(A[i,i])
        for j in range(i+1, M):
            s = sum(L[i,k]*L[j,k] for k in range(i))
            L[j,i] = (A[j,i] - s) / L[i,i]
    return L

