def apply_low_pass_filter(image_array, frequency_threshold):
    if len(image_array) == 0 or len(image_array[0]) == 0:
        return image_array, image_array
    elif len(image_array.shape) != 2 or image_array.shape[0] != image_array.shape[1]:
        raise ValueError("Input must be a square matrix")
    elif frequency_threshold <= 0:
        raise ValueError("Frequency threshold must be positive")

