def n_tangle(psi):
    if len(psi) == 0:
        raise ValueError("Empty input")
    if np.allclose(psi, 0):
        raise ValueError("Zero vector")
    n = int(np.log2(len(psi)))
    sigma_y = np.array([[0, -1j], [1j, 0]])
    psi_tilde = np.conjugate(psi)
    tangle = np.abs(np.dot(psi, tensor_product(*[sigma_y] * n) @ psi_tilde)) ** 2
    return tangle

