def MC(sigma, epsilon, T, init_positions, MC_steps, dispSize):
    beta = 1 / T
    N = len(init_positions)
    E_trace = []
    current_positions = np.copy(init_positions)
    for _ in range(MC_steps):
        i = np.random.randint(N)
        new_position = current_positions[i] + np.random.normal(0, dispSize, 3)
        if np.all(np.abs(new_position) <= sigma):
            U_new = U_system(current_positions, sigma, epsilon)
            U_old = U_system(new_position, sigma, epsilon)
            acceptance_ratio = min(1, np.exp(-beta * (U_new - U_old)))
            if np.random.rand() < acceptance_ratio:
                current_positions[i] = new_position
        E_trace.append(U_system(current_positions, sigma, epsilon))
    return E_trace

