def Nbody(uin, mass, dt, t0, t1):
    N = len(mass)
    u = np.array(uin)

    def force(i, u):
        F = np.zeros(6)
        for j in range(N):
            if i != j:
                r = u[j][:3] - u[i][:3]
                r_mag = np.linalg.norm(r)
                F += mass[j] * r / (r_mag ** 3) * mass[i]
        return F

    def derivative(u, t):
        du = np.zeros((N, 6))
        for i in range(N):
            du[i] = u[i][3:] + force(i, u) / mass[i]
        return du

    def rk4(u0, dt, t0, t1):
        t = t0
        u = u0
        while t < t1:
            k1 = derivative(u, t)
            k2 = derivative(u + dt * k1 / 2, t + dt / 2)
            k3 = derivative(u + dt * k2 / 2, t + dt / 2)
            k4 = derivative(u + dt * k3, t + dt)
            u += dt * (k1 + 2 * k2 + 2 * k3 + k4) / 6
            t += dt
        return u

    if N == 0:
        return np.array([])

    for m in mass:
        if m <= 0:
            raise ValueError("Particle masses must be positive")

    uout = rk4(u, dt, t0, t1)
    return uout.tolist()

